BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwBytesAvailable = 0;
    DWORD dwRead = 0;
    LPBYTE pBuffer = NULL;
    BOOL bResult = FALSE;

    // Check number of bytes available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwBytesAvailable, NULL)) {
        // Log error
        return FALSE;
    }

    if (dwBytesAvailable == 0) {
        // Log error
        return FALSE;
    }

    // Allocate memory to read data
    pBuffer = (LPBYTE)HeapAlloc(GetProcessHeap(), MEM_ZEROINIT, dwBytesAvailable + 1);
    if (!pBuffer) {
        // Log error
        return FALSE;
    }

    // Read data from the pipe
    if (!ReadFile(pipe, pBuffer, dwBytesAvailable, &dwRead, NULL) || dwRead != dwBytesAvailable) {
        // Log error
        HeapFree(GetProcessHeap(), 0, pBuffer);
        return FALSE;
    }

    // Check if the data is NULL-terminated
    if (pBuffer[dwBytesAvailable - 1] != '\0') {
        // Log error
        HeapFree(GetProcessHeap(), 0, pBuffer);
        return FALSE;
    }

    // Extract data from the buffer
    sud->workingDirectory = (LPWSTR)pBuffer;
    sud->commandLineOptions = wcschr(sud->workingDirectory, L'\0') + 1;
    sud->standardInput = wcschr(sud->commandLineOptions, L'\0') + 1;

    // Verify data integrity
    if (!sud->workingDirectory || !sud->commandLineOptions || !sud->standardInput) {
        // Log error
        HeapFree(GetProcessHeap(), 0, pBuffer);
        return FALSE;
    }

    // Successfully retrieved data
    bResult = TRUE;
    return bResult;
}

BOOL ReadStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwRead = 0;
    DWORD dwAvail = 0;
    DWORD dwMsgSize = 0;
    BOOL bResult = FALSE;
    LPVOID lpBuffer = NULL;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwAvail, &dwMsgSize)) {
        LogError("PeekNamedPipe failed with error %d", GetLastError());
        return FALSE;
    }

    if (dwAvail == 0) {
        LogError("No data available in the pipe");
        return FALSE;
    }

    lpBuffer = HeapAlloc(GPTR, dwAvail);
    if (lpBuffer == NULL) {
        LogError("Memory allocation failed");
        return FALSE;
    }

    if (!ReadFile(pipe, lpBuffer, dwAvail, &dwRead, NULL)) {
        LogError("ReadFile failed with error %d", GetLastError());
        goto cleanup;
    }

    if (dwRead == 0) {
        LogError("No data was read from the pipe");
        goto cleanup;
    }

    if (((LPSTR)lpBuffer)[dwRead - 1] != '\0') {
        LogError("Received data is not NULL-terminated");
        goto cleanup;
    }

    // Extract working directory, command line, and stdin from the buffer
    sud->working_directory = strdup((char *)lpBuffer);
    sud->command_line = strdup((char *)lpBuffer);
    sud->standard_input = strdup((char *)lpBuffer);

    bResult = TRUE;

cleanup:
    if (!bResult) {
        if (lpBuffer) {
            HeapFree(GPTR, lpBuffer);
        }
    }

    return bResult;
}

