BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwRead = 0;
    DWORD dwAvailable = 0;
    DWORD dwTotalBytes = 0;
    char *buffer = NULL;
    BOOL result = FALSE;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwAvailable, &dwTotalBytes)) {
        LogError("PeekNamedPipe failed");
        return FALSE;
    }

    if (dwAvailable == 0 || dwTotalBytes == 0) {
        LogError("No data available in the pipe");
        return FALSE;
    }

    buffer = (char *)malloc(dwTotalBytes + 1);
    if (buffer == NULL) {
        LogError("Memory allocation failed");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, dwTotalBytes, &dwRead, NULL) || dwRead != dwTotalBytes) {
        LogError("Failed to read full data from pipe");
        free(buffer);
        return FALSE;
    }

    // Ensure NULL-termination
    buffer[dwTotalBytes] = '\0';

    // Parse data from buffer into STARTUP_DATA structure
    sud->working_directory = strtok(buffer, "\n");
    sud->command_line_options = strtok(NULL, "\n");
    sud->standard_input = strtok(NULL, "\n");

    if (sud->working_directory == NULL || sud->command_line_options == NULL || sud->standard_input == NULL) {
        LogError("Malformed data in pipe");
        free(buffer);
        return FALSE;
    }

    result = TRUE;
    free(buffer);
    return result;
}

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD cbRead = 0;
    DWORD cbAvail = 0;
    DWORD cbMsg = 0;
    CHAR *buffer = NULL;
    BOOL bResult = FALSE;

    // Check number of bytes available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &cbAvail, &cbMsg)) {
        LogError("PeekNamedPipe failed with error %d", GetLastError());
        return FALSE;
    }

    if (cbAvail == 0 || cbMsg != 0) {
        LogError("No data available or data is not a message");
        return FALSE;
    }

    // Allocate memory to read the data
    buffer = (CHAR *)HeapAlloc(GPTR, cbAvail);
    if (buffer == NULL) {
        LogError("Memory allocation failed for buffer");
        return FALSE;
    }

    // Read data from the pipe
    if (!ReadFile(pipe, buffer, cbAvail, &cbRead, NULL)) {
        LogError("ReadFile failed with error %d", GetLastError());
        goto Cleanup;
    }

    if (cbRead != cbAvail) {
        LogError("Read data size does not match available data size");
        goto Cleanup;
    }

    // Ensure the data is NULL-terminated
    if (buffer[cbRead - 1] != '\0') {
        LogError("Startup data is not NULL-terminated");
        goto Cleanup;
    }

    // Extract working directory, command line, and standard input
    sud->workingDirectory = strdup(buffer);
    if (sud->workingDirectory == NULL) {
        LogError("Failed to duplicate working directory string");
        goto Cleanup;
    }

    sud->commandLine = strdup(buffer);
    if (sud->commandLine == NULL) {
        LogError("Failed to duplicate command line string");
        goto Cleanup;
    }

    sud->standardInput = _tcsdup(buffer);
    if (sud->standardInput == NULL) {
        LogError("Failed to duplicate standard input string");
        goto Cleanup;
    }

    bResult = TRUE;

Cleanup:
    if (!bResult) {
        // Clean up
        if (buffer) {
            HeapFree(buffer);
        }
        if (sud->workingDirectory) {
            free(sud->workingDirectory);
        }
        if (sud->commandLine) {
            free(sud->commandLine);
        }
        if (sud->standardInput) {
            free(sud->standardInput);
        }
    }

    return bResult;
}

