BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwBytesAvailable = 0;
    DWORD dwRead = 0;
    DWORD dwTotalBytesAvail = 0;
    DWORD dwBytesLeftThisMessage = 0;
    LPVOID lpvBuffer = NULL;
    CHAR *pData = NULL;
    CHAR *pEnd = NULL;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwTotalBytesAvail, &dwBytesLeftThisMessage)) {
        return FALSE;
    }

    if (dwTotalBytesAvail == 0) {
        return FALSE;
    }

    lpvBuffer = HeapAlloc(GPTR, dwTotalBytesAvail + 1);
    if (lpvBuffer == NULL) {
        return FALSE;
    }

    if (!ReadFile(pipe, lpvBuffer, dwTotalBytesAvail, &dwRead, NULL)) {
        HeapFree(lpvBuffer);
        return FALSE;
    }

    pData = (CHAR *)lpvBuffer;
    pEnd = pData + dwRead;

    if (pEnd - pData < 1 || *pEnd != '\0') {
        HeapFree(lpvBuffer);
        return FALSE;
    }

    sud->working_dir = pData;
    sud->command_line = pData;
    sud->stdin_input = pData;

    CHAR *pWorkingDir = strchr(pData, '\0');
    if (pWorkingDir == NULL) {
        HeapFree(lpvBuffer);
        return FALSE;
    }

    *pWorkingDir++ = '\0';
    sud->working_dir = pData;
    sud->command_line = pWorkingDir;

    CHAR *pCommandLine = strchr(pWorkingDir, '\0');
    if (pCommandLine == NULL) {
        HeapFree(lpvBuffer);
        return FALSE;
    }

    *pCommandLine++ = '\0';
    sud->stdin_input = pCommandLine;

    return TRUE;
}
